import { defineConfig } from "oxfmt";
import ultracite from "ultracite/oxfmt";

export default defineConfig({
  ...ultracite,
  ignorePatterns: [
    ...(ultracite.ignorePatterns ?? []),
    // Prose is hand-wrapped; `proseWrap: "never"` would join every paragraph.
    "**/*.md",
    // Rust sources, Cargo manifests and the session fixtures the Rust tests
    // read byte for byte.
    "crates",
    "**/*.toml",
    "tests",
    // Generated by `bunx shadcn add`, rewritten on every `bun run upgrade`.
    "packages/ui/src/components",
    "packages/ui/src/hooks",
    "packages/ui/src/lib",
    // Generated from the Rust protocol, core and server crates.
    "packages/view-core/src/*.gen.ts",
    "apps/inspector/test/fixtures",
    "scripts/release/npm",
    // Vendored skills, pinned by content hash in skills-lock.json.
    "**/.agents/skills",
    "**/.claude/skills",
  ],
});
